<script>
document.querySelectorAll('[data-custom-input]').forEach(function(input){
  var type=input.dataset.customInput, list=document.querySelector('[data-custom-checks="'+type+'"]');
  function add(){var value=input.value.trim();if(!value)return;input.value='';fetch('{{ route('admin.attorney-options.store') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body:'type='+encodeURIComponent(type)+'&name='+encodeURIComponent(value)}).then(function(response){if(!response.ok)throw new Error('Unable to add option');location.reload()}).catch(function(){input.value=value;alert('Option could not be added. Please try again.');});}
  input.addEventListener('change',add); input.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();add()}}); input.form.addEventListener('submit',add);
});
</script>
